# ─────────────────────────────────────────────────────────────
# Tool execution functions
# ─────────────────────────────────────────────────────────────


async def execute_tool(tool_name: str, tool_input: dict) -> str:
    """
    Execute a tool by name with the given input. Returns JSON string result.
    This is the single dispatch point called by the agent loop.
    """
    client = get_client()

    try:
        if tool_name == "synapse_ping":
            result = await client.ping()
            return json.dumps({"status": "connected", "details": result}, indent=2, default=str)

        elif tool_name == "synapse_scene_info":
            result = await client.scene_info()
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_inspect_scene":
            result = await client.inspect_scene(
                root=tool_input.get("root", "/"),
                max_depth=tool_input.get("max_depth", 3),
                context_filter=tool_input.get("context_filter", ""),
            )
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_inspect_selection":
            result = await client.inspect_selection(
                depth=tool_input.get("depth", 1),
            )
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_inspect_node":
            result = await client.inspect_node(
                node=tool_input["node_path"],
                include_code=tool_input.get("include_code", True),
                include_geometry=tool_input.get("include_geometry", True),
                include_expressions=tool_input.get("include_expressions", True),
            )
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_execute":
            return await _execute_with_verification(client, tool_input)

        elif tool_name == "synapse_render_preview":
            payload = {k: v for k, v in tool_input.items() if v is not None}
            result = await client.render(**payload)
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_knowledge_lookup":
            result = await client.knowledge_lookup(tool_input["query"])
            return json.dumps(result, indent=2, default=str)

        # Living Memory tools
        elif tool_name == "synapse_project_setup":
            result = await client.project_setup()
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_memory_write":
            result = await client.memory_write(
                entry_type=tool_input["entry_type"],
                content=tool_input.get("content", {}),
                scope=tool_input.get("scope", "scene"),
            )
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_memory_query":
            result = await client.memory_query(
                query=tool_input["query"],
                scope=tool_input.get("scope", "all"),
                type_filter=tool_input.get("type_filter", ""),
            )
            return json.dumps(result, indent=2, default=str)

        elif tool_name == "synapse_memory_status":
            result = await client.memory_status()
            return json.dumps(result, indent=2, default=str)

        else:
            return json.dumps({"error": f"Unknown tool: {tool_name}"})

    except SynapseExecutionError as e:
        return json.dumps(
            {
                "executed": False,
                "error": str(e),
                "rolled_back": True,
                "hint": "The scene was rolled back. Check the code and try again.",
            },
            indent=2,
        )
    except Exception as e:
        return json.dumps({"error": str(e)}, indent=2)


async def _execute_with_verification(client: SynapseClient, tool_input: dict) -> str:
    """Execute Python code and optionally verify node paths after."""
    code = tool_input["code"]
    description = tool_input.get("description", "")

    logger.info("Executing: %s", description or "unlabeled operation")

    try:
        result = await client.execute_python(code)

        # Verification pass
        verify_paths_str = tool_input.get("verify_paths", "")
        if verify_paths_str:
            paths = [p.strip() for p in verify_paths_str.split(",") if p.strip()]
            verify_code = (
                "import hou, json\n"
                "checks = {}\n"
                f"for path in {paths}:\n"
                "    node = hou.node(path)\n"
                "    checks[path] = {\n"
                "        'exists': node is not None,\n"
                "        'type': node.type().name() if node else None,\n"
                "        'errors': node.errors() if node else None\n"
                "    }\n"
                "result = json.dumps(checks, indent=2)\n"
            )
            verification = await client.execute_python(verify_code)
            return json.dumps(
                {
                    "executed": True,
                    "result": result,
                    "verification": json.loads(verification) if isinstance(verification, str) else verification,
                    "description": description,
                },
                indent=2,
                default=str,
            )

        return json.dumps(
            {"executed": True, "result": result, "description": description},
            indent=2,
            default=str,
        )

    except SynapseExecutionError as e:
        return json.dumps(
            {
                "executed": False,
                "error": str(e),
                "rolled_back": True,
                "description": description,
                "hint": "The scene was rolled back to its previous state. Check the code and try again.",
            },
            indent=2,
        )

"""
synapse_tone.py — Coaching language for Synapse communications.

Every message the artist sees should pass the validation test:
"Would this message make an artist having a rough day want to keep going
 or close the application?"

Principles:
1. Never blame — "I couldn't find" not "you gave wrong path"
2. Plain language first — technical details can follow
3. Always offer a next step — every error suggests what to try
4. "We/I" framing — collaborative, not diagnostic
5. Forward momentum — success messages imply "what's next"
"""

import re
from typing import Any


def enrich_error_message(error: str, code: str) -> str:
    """Transform a raw error into coaching language with suggestions."""
    enriched = error

    # Node not found
    if "not found" in error.lower() or "couldn't find" in error.lower():
        path_match = re.search(r"['\"`]?(/[a-zA-Z0-9_/]+)['\"`]?", error)
        if path_match:
            path = path_match.group(1)
            enriched = (
                f"Couldn't find a node at `{path}` — it might have been renamed or "
                f"might not exist yet. I can search the scene to find the right path."
            )
        else:
            enriched = (
                "Something I expected to find wasn't there. Let me inspect the "
                "scene to get re-oriented."
            )

    # Parameter errors
    elif "parameter" in error.lower() or "parm" in error.lower():
        enriched = (
            f"Hit a parameter issue: {error}. H21 USD nodes use encoded parameter names "
            f"(like `xn__inputsintensity_i0a` instead of `intensity`). "
            f"I can inspect the node to find the exact parameter names."
        )

    # Permission / path errors
    elif "permission" in error.lower() or "writable" in error.lower():
        enriched = (
            "Couldn't write to the output path — might be a permissions issue. "
            "I'll try using C:/Users/User/.synapse/ instead."
        )

    # Type errors
    elif "NoneType" in error or "AttributeError" in error:
        enriched = (
            "Something I expected to exist wasn't there yet — likely a node or "
            "parameter that wasn't created in a previous step. Let me check "
            "the scene state and try a different approach."
        )

    # Generic fallback
    elif not any(phrase in enriched for phrase in ["I can", "I'll", "Let me"]):
        enriched = f"{error}. Let me take a different approach."

    return enriched


def format_success_message(description: str, result_data: Any) -> str:
    """Format a success result with forward momentum."""
    if not isinstance(result_data, dict):
        return f"{description} — done."

    verification = result_data.get("verification", {})
    parts = [f"{description} — done."]

    if verification and isinstance(verification, dict):
        all_ok = all(
            v.get("exists", False)
            for v in verification.values()
            if isinstance(v, dict)
        )
        error_count = sum(
            1
            for v in verification.values()
            if isinstance(v, dict) and v.get("errors")
        )
        if all_ok and error_count == 0:
            parts.append("Verified — everything checks out.")
        elif not all_ok:
            missing = [
                k
                for k, v in verification.items()
                if isinstance(v, dict) and not v.get("exists")
            ]
            parts.append(
                f"Heads up: {', '.join(missing)} didn't make it. Let me investigate."
            )

    return " ".join(parts)

        },
    },
    {
        "name": "synapse_memory_status",
        "description": (
            "Get the current Living Memory system status — evolution stage "
            "(charmander/charmeleon/charizard), file sizes, session count, "
            "and agent task state."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
]


